export interface SlipData {
  amount: string | null;
  referenceCode: string | null;
  senderName: string | null;
  receiverName: string | null;
  receiverAccount: string | null;
}

export const parseSlipText = (ocrText: string): SlipData => {
  const amountMatch = ocrText.match(/จํานวนเงิน\s+([\d.,]+)/);
  const referenceMatch = ocrText.match(/รหัสอ้างอิง[:\s]+(\d+)/);
  const senderMatch = ocrText.match(/จาก\s+([^\n]+)/);
  const receiverMatch = ocrText.match(/ถึง\s+([^\n]+)/);
  const accountMatch = ocrText.match(/(\d{2,}x{2,}\d{4})|\d{4}$/);

  return {
    amount: amountMatch ? amountMatch[1] : null,
    referenceCode: referenceMatch ? referenceMatch[1] : null,
    senderName: senderMatch ? senderMatch[1].trim() : null,
    receiverName: receiverMatch ? receiverMatch[1].trim() : null,
    receiverAccount: accountMatch ? accountMatch[0].replace(/x/g, "") : null,
  };
};
